package com.productionhouse.crm.audio.singer.api;
import com.productionhouse.crm.audio.singer.dto.*;import com.productionhouse.crm.audio.singer.service.SingerProfileService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/audio/singers") public class SingerProfileController{private final SingerProfileService service;public SingerProfileController(SingerProfileService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('SINGER_READ')") public Page<SingerResponse> list(@RequestParam(required=false)String q,@RequestParam(required=false)String language,@RequestParam(required=false)String status,@RequestParam(required=false)Boolean active,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return service.list(q,language,status,active,page,size,sort,direction);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('SINGER_READ')") public SingerResponse get(@PathVariable Long id){return service.get(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('SINGER_WRITE')") public SingerResponse create(@Valid @RequestBody SingerRequest request){return service.create(request);}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('SINGER_WRITE')") public SingerResponse update(@PathVariable Long id,@Valid @RequestBody SingerRequest request){return service.update(id,request);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority('SINGER_DELETE')") public void delete(@PathVariable Long id){service.delete(id);}}
